/** Independent Driver entry. Numeric admission remains blocked by the existing broker/client policy. */
(async()=>{const workspace=document.getElementById('workspace'),status=document.getElementById('portal-login-status');let auth;
 const versioned=p=>window.TAXIQAID_ASSET_VERSIONS?.[p]?p+'?v='+window.TAXIQAID_ASSET_VERSIONS[p]:p;
 const script=p=>new Promise((resolve,reject)=>{const e=document.createElement('script');e.async=false;const hex=window.TAXIQAID_ASSET_VERSIONS?.[p];if(hex)e.integrity='sha256-'+btoa(String.fromCharCode(...hex.match(/../g).map(n=>parseInt(n,16))));e.src=versioned(p);e.onload=resolve;e.onerror=reject;document.head.append(e);});
 try{if(window.TAXIQAID_DEDICATED_AUTH?.enabled!==true){document.getElementById('portal-login-form').addEventListener('submit',event=>{event.preventDefault();document.getElementById('portal-password').value='';status.textContent='Driver sign-in is unavailable until secure account provisioning is enabled.';});workspace.hidden=false;document.getElementById('boot-status').remove();return;}if(!window.supabase?.createClient)throw new Error('Authentication SDK unavailable.');for(const p of ['shared/config.js','shared/permission-catalog.js','shared/permission-model.js','shared/auth-contract.js','shared/auth-client.js','shared/access-runtime.js'])await script(p);
 auth=TaxiQaidAuthClient.create({client:supabaseClient,...{url:TAXIQAID_DEDICATED_AUTH.url,key:TAXIQAID_DEDICATED_AUTH.publicKey,brokerUrl:TAXIQAID_DEDICATED_AUTH.brokerUrl,enabled:TAXIQAID_DEDICATED_AUTH.enabled},accountType:'Driver',onClear:()=>{TaxiQaidAccess.reset();document.getElementById('portal-password').value='';},onAccess:context=>{if(context.accountType!=='Driver')throw new Error('Driver access required.');status.textContent='Driver data integration is not activated. Contact your administrator.';}});
 document.getElementById('portal-login-form').addEventListener('submit',async event=>{event.preventDefault();const input=document.getElementById('portal-password'),value=input.value;input.value='';try{await auth.login(document.getElementById('portal-iqama').value,value);}catch{status.textContent='Driver sign-in is unavailable until secure account provisioning is enabled. Contact your administrator.';}});
 window.TaxiQaidDriverEntry=Object.freeze({auth});workspace.hidden=false;document.getElementById('boot-status').remove();void auth.start();
 }catch{document.getElementById('boot-status').textContent='Driver sign-in is unavailable. Reload or contact your administrator.';workspace.hidden=true;}})();
